<?php

declare(strict_types=1);

namespace WPCalibrate\HtmlBridge\Import;

if (!defined('ABSPATH')) {
    exit;
}

/**
 * Class ImportManifest
 *
 * Encapsulates the structured manifest generated by pre-import scanning.
 */
final class ImportManifest
{
    /**
     * Manifest payload array.
     *
     * @var array<string, mixed>
     */
    private array $data;

    /**
     * Constructor.
     *
     * @param array<string, mixed> $data
     */
    public function __construct(array $data)
    {
        $this->data = $data;
    }

    /**
     * Create manifest instance from JSON string.
     *
     * @param string $json
     * @return self
     */
    public static function fromJson(string $json): self
    {
        $decoded = json_decode($json, true);
        if (!is_array($decoded)) {
            $decoded = [];
        }
        return new self($decoded);
    }

    /**
     * Convert manifest to array.
     *
     * @return array<string, mixed>
     */
    public function toArray(): array
    {
        return $this->data;
    }

    /**
     * Serialize manifest to JSON string.
     *
     * @return string
     */
    public function toJson(): string
    {
        return (string) wp_json_encode($this->data, JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT);
    }

    public function getUuid(): string
    {
        return (string) ($this->data['uuid'] ?? '');
    }

    public function getHomepage(): string
    {
        return (string) ($this->data['homepage'] ?? '');
    }

    public function setHomepage(string $homepage): void
    {
        $this->data['homepage'] = $homepage;
    }

    /**
     * @return array<string, array<string, mixed>>
     */
    public function getPages(): array
    {
        return (array) ($this->data['pages'] ?? []);
    }

    /**
     * Update page settings (title, slug, included).
     *
     * @param string $path
     * @param array<string, mixed> $pageUpdates
     */
    public function updatePage(string $path, array $pageUpdates): void
    {
        if (isset($this->data['pages'][$path])) {
            $this->data['pages'][$path] = array_merge($this->data['pages'][$path], $pageUpdates);
        }
    }

    /**
     * @return array<string>
     */
    public function getCssFiles(): array
    {
        return (array) ($this->data['css_files'] ?? []);
    }

    /**
     * @return array<string>
     */
    public function getJsFiles(): array
    {
        return (array) ($this->data['js_files'] ?? []);
    }

    /**
     * @return array<string>
     */
    public function getImages(): array
    {
        return (array) ($this->data['images'] ?? []);
    }

    /**
     * @return array<string>
     */
    public function getFonts(): array
    {
        return (array) ($this->data['fonts'] ?? []);
    }

    /**
     * @return array<string>
     */
    public function getWarnings(): array
    {
        return (array) ($this->data['warnings'] ?? []);
    }

    public function addWarning(string $warning): void
    {
        $this->data['warnings'][] = $warning;
    }

    /**
     * @return array<mixed>
     */
    public function getForms(): array
    {
        return (array) ($this->data['forms'] ?? []);
    }

    /**
     * @return array<mixed>
     */
    public function getNavigationCandidates(): array
    {
        return (array) ($this->data['navigation_candidates'] ?? []);
    }
}
